"""Shared national report support, consolidated as inspectable plain source.

Expand with --extract=PRIVATE_DIRECTORY; source syntax check with --check-runtime.
No fitted estimates, microdata or finished reports are embedded here.
"""
import argparse,json,sys,subprocess
from pathlib import Path

